
  create table "public"."analytics_events" (
    "id" bigint generated by default as identity not null,
    "account_id" bigint not null,
    "event_type" text not null,
    "properties" jsonb not null default '{}'::jsonb,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."analytics_events" enable row level security;

CREATE INDEX analytics_events_account_created ON public.analytics_events USING btree (account_id, created_at DESC);

CREATE UNIQUE INDEX analytics_events_pkey ON public.analytics_events USING btree (id);

alter table "public"."analytics_events" add constraint "analytics_events_pkey" PRIMARY KEY using index "analytics_events_pkey";

alter table "public"."analytics_events" add constraint "analytics_events_account_id_fkey" FOREIGN KEY (account_id) REFERENCES public.accounts(id) ON DELETE CASCADE not valid;

alter table "public"."analytics_events" validate constraint "analytics_events_account_id_fkey";

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.ai_cost_per_active_family()
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_total_cost numeric;
  v_active_accounts bigint;
begin
  select coalesce(sum(cost_usd), 0) into v_total_cost
  from public.ai_usage_meter
  where account_id = public.current_context_id();

  select count(*) into v_active_accounts
  from public.accounts
  where id = public.current_context_id();

  if v_active_accounts = 0 then
    return 0;
  end if;

  return round(v_total_cost / v_active_accounts, 4);
end;
$function$
;

create or replace view "public"."analytics_events_summary" as  SELECT account_id,
    count(*) FILTER (WHERE (event_type = 'item_filed'::text)) AS items_filed,
    count(*) FILTER (WHERE (event_type = 'duplicate_confirmed'::text)) AS duplicates_confirmed,
    count(*) FILTER (WHERE (event_type = 'reference_call_logged'::text)) AS reference_calls_logged,
    count(*) FILTER (WHERE (event_type = 'channel_capture'::text)) AS channel_captures,
    avg(((properties ->> 'time_to_file_ms'::text))::bigint) FILTER (WHERE (event_type = 'time_to_file'::text)) AS avg_time_to_file_ms,
    count(*) AS total_events
   FROM public.analytics_events
  GROUP BY account_id;


CREATE OR REPLACE FUNCTION public.cross_account_leak_reports()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count bigint;
begin
  select count(*) into v_count
  from public.analytics_events
  where account_id != public.current_context_id();
  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.duplicate_flag_false_positive_rate()
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_total bigint;
  v_dismissed bigint;
begin
  select count(*) into v_total
  from public.analytics_events
  where account_id = public.current_context_id()
    and event_type = 'duplicate_confirmed';

  if v_total = 0 then
    return 0;
  end if;

  select count(*) into v_dismissed
  from public.analytics_events
  where account_id = public.current_context_id()
    and event_type = 'duplicate_confirmed'
    and (properties->>'dismissed')::boolean = true;

  return round((v_dismissed::numeric / v_total::numeric) * 100, 2);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.misrouted_channel_items()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count bigint;
begin
  select count(*) into v_count
  from public.inbox_items
  where account_id = public.current_context_id()
    and (
      source = 'shadchan' and connection_id is null
      or source in ('email', 'whatsapp', 'sms') and sender_needs_confirmation
    );
  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trial_to_paid_conversion()
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_trial_started bigint;
  v_active_subscriptions bigint;
begin
  select count(*) into v_trial_started
  from public.accounts
  where trial_end is not null;

  if v_trial_started = 0 then
    return 0;
  end if;

  select count(*) into v_active_subscriptions
  from public.accounts
  where subscription_status = 'active'
    and plan is not null;

  return round((v_active_subscriptions::numeric / v_trial_started::numeric) * 100, 2);
end;
$function$
;

